    assert (
        checkForOverlappingGrants(
            {
                'operationParam': {
                    'operationFrequencyRange': {
                        'lowFrequency': 3610000000,
                        'highFrequency': 3620000000
                    }
                }
            },
            {'lowFrequency': 3620000000, 'highFrequency': 3630000000}
        )
        == False
    );;
}

